<?php
require_once __DIR__.'/../includes/supervision-xlsx.php';
function check_import(bool $ok,string $message):void {if(!$ok)throw new Exception($message);}
$bytes=supervisor_write_xlsx([['Pedido mensual'],[],[],['EAN','Producto','UXB'],['96385074','Uno',12],['4.006381333931E+12','Dos',6],['x01234565','Corregir',2],[],['EAN','Otra categoría'],['01234565','Tres',2],['123','Incompleto',1],['=96385074','Texto',1]]);
$p=supervisor_parse_xlsx($bytes);check_import($p['header']===4&&$p['suggested']==='A'&&$p['row_count']===3&&$p['issue_count']===3,'detect header, scientific, repeated titles and issues');
try{supervisor_parse_xlsx($bytes,'A');throw new Exception('Expected validation');}catch(CatalogException $e){check_import($e->status===422,'invalid blocked');}
$fixed=supervisor_parse_xlsx($bytes,'A',['header'=>'4','corrections'=>'{"7":"01234565"}','exclude_invalid'=>'1']);check_import($fixed['row_count']===4&&$fixed['ean_rows'][7]==='01234565'&&!isset($fixed['ean_rows'][11]),'explicit fixes and exclusions');
$out=supervisor_compare_xlsx($bytes,$fixed['sheet_path'],$fixed['ean_rows'],['01234565'=>9],$fixed['header']);supervisor_archive($out,function($zip){[, $rows]=supervisor_cells($zip,'xl/worksheets/sheet1.xml');check_import($rows[4]['D']['value']==='Stock (unidades)'&&$rows[7]['D']['value']==='9'&&!isset($rows[11]['D'])&&$rows[7]['A']['value']==='x01234565','original and rejected rows preserved; header aligned');});
check_import(!valid_product_ean(supervisor_ean('7,79389E+12')),'rounded scientific is never expanded into inferred EAN');
$plain=supervisor_write_xlsx([['96385074','No titles'],['01234565','Second']]);$p=supervisor_parse_xlsx($plain,'A');check_import($p['header']===0&&$p['row_count']===2,'headerless keeps first product');$out=supervisor_compare_xlsx($plain,$p['sheet_path'],$p['ean_rows'],['96385074'=>8],0);supervisor_archive($out,function($zip){[, $r]=supervisor_cells($zip,'xl/worksheets/sheet1.xml');check_import($r[1]['C']['value']==='8','headerless first row amount');});
try{supervisor_parse_xlsx($bytes,'A',['sheet'=>'../outside.xml']);throw new Exception('Expected invalid sheet');}catch(CatalogException $e){check_import($e->status===422,'sheet selection restricted');}

$multi=supervisor_archive($bytes,function($zip){$zip['xl/worksheets/sheet2.xml']=$zip['xl/worksheets/sheet1.xml']->getContent();$cover=supervisor_write_xlsx([['Portada']]);$zip['xl/worksheets/sheet1.xml']=supervisor_archive($cover,fn($z)=>$z['xl/worksheets/sheet1.xml']->getContent());$xml=$zip['xl/workbook.xml']->getContent();$zip['xl/workbook.xml']=str_replace('</sheets>','<sheet name="Productos" sheetId="2" r:id="rId2"/></sheets>',$xml);$xml=$zip['xl/_rels/workbook.xml.rels']->getContent();$zip['xl/_rels/workbook.xml.rels']=str_replace('</Relationships>','<Relationship Id="rId2" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/worksheet" Target="worksheets/sheet2.xml"/></Relationships>',$xml);return file_get_contents($zip->getPath());});
$mp=supervisor_parse_xlsx($multi,'A',['exclude_invalid'=>'1']);$mo=supervisor_compare_xlsx($multi,$mp['sheet_path'],$mp['ean_rows'],['96385074'=>21],$mp['header']);$cover=supervisor_archive($multi,fn($z)=>$z['xl/worksheets/sheet1.xml']->getContent());supervisor_archive($mo,function($z)use($cover){check_import($z['xl/worksheets/sheet1.xml']->getContent()===$cover,'unselected cover unchanged');[, $r]=supervisor_cells($z,'xl/worksheets/sheet2.xml');check_import($r[4]['D']['value']==='Stock (unidades)'&&$r[5]['D']['value']==='21','selected second sheet export');});
$p=supervisor_parse_xlsx($multi);check_import(count($p['sheets'])===2&&$p['sheet_path']==='xl/worksheets/sheet2.xml'&&$p['header']===4,'auto selects products after cover sheet');$p=supervisor_parse_xlsx($multi,'',['sheet'=>'xl/worksheets/sheet1.xml','preview'=>true]);check_import($p['row_count']===0&&$p['sheet_path']==='xl/worksheets/sheet1.xml','manual sheet honored');
echo "OK: flexible headers, headerless first row, full scientific EAN, repeated headers, corrections, explicit exclusions and unchanged source export.\n";
